[CmdletBinding()]
param(
    [string]$Path = "",
    [switch]$Install,
    [switch]$Uninstall,
    [switch]$AutoHeal,
    [switch]$Silent,
    [switch]$NoRestart,
    [switch]$PauseAtEnd
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

$backupDir = Join-Path ([System.IO.Path]::GetTempPath()) "claude-zh-tw-backup"
$utf8NoBom = [System.Text.UTF8Encoding]::new($false)

# 內嵌臺灣正體中文壓縮資料庫 (Gzip + Base64，提供單檔免外部依賴獨立運作能力)
$B64_DESKTOP = ""

$B64_STATSIG = ""

$B64_DYNAMIC = ""

$B64_ION = ""

function Test-IsAdministrator {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Ensure-Administrator {
    param([string[]]$Arguments = @())

    if (Test-IsAdministrator) {
        return
    }

    $argumentList = @(
        "-NoProfile",
        "-ExecutionPolicy",
        "Bypass",
        "-File",
        "`"$PSCommandPath`""
    ) + $Arguments

    if ($Silent -or $AutoHeal) {
        try {
            $proc = Start-Process -FilePath "powershell.exe" -Verb RunAs -ArgumentList $argumentList -WindowStyle Hidden -PassThru -ErrorAction Stop
            if ($proc) { $proc.WaitForExit() }
            exit 0
        } catch {
            return
        }
    } else {
        try {
            $proc = Start-Process -FilePath "powershell.exe" -Verb RunAs -ArgumentList $argumentList -PassThru -ErrorAction Stop
            exit 0
        } catch {
            Write-Host "  [提示] 無法自動喚起 UAC 系統管理員提權視窗 ($($_.Exception.Message))" -ForegroundColor Yellow
            Write-Host "  若安裝過程出現權限不足，請以滑鼠右鍵點選「以系統管理員身分執行」。" -ForegroundColor Yellow
            Write-Host ""
            return
        }
    }
}

function Wait-BeforeExit {
    if ($Silent -or $AutoHeal) { return }
    Write-Host ""
    [void](Read-Host "請按 Enter 鍵關閉視窗")
}

function Write-Utf8File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Content
    )
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        [System.IO.Directory]::CreateDirectory($parent) | Out-Null
    }
    [System.IO.File]::WriteAllText($Path, $Content, $utf8NoBom)
}

function Decompress-B64GzToFile {
    param(
        [Parameter(Mandatory = $true)][string]$Base64,
        [Parameter(Mandatory = $true)][string]$OutPath
    )
    $parent = Split-Path -Parent $OutPath
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        [System.IO.Directory]::CreateDirectory($parent) | Out-Null
    }
    Grant-ExistingFileWriteAccess -Path $OutPath
    $bytes = [System.Convert]::FromBase64String($Base64)
    $ms = [System.IO.MemoryStream]::new($bytes)
    $gz = [System.IO.Compression.GzipStream]::new($ms, [System.IO.Compression.CompressionMode]::Decompress)
    $fs = [System.IO.File]::Create($OutPath)
    $gz.CopyTo($fs)
    $fs.Close()
    $gz.Close()
    $ms.Close()
}

function Find-ClaudePath {
    param([string]$ManualPath = "")

    # 0. 手動指定路徑優先
    if ($ManualPath -and (Test-Path -LiteralPath $ManualPath)) {
        if (Test-Path -LiteralPath (Join-Path $ManualPath "app\resources")) { return $ManualPath }
        if (Test-Path -LiteralPath (Join-Path $ManualPath "resources")) { return $ManualPath }
        if (Split-Path $ManualPath -Leaf -ieq "resources") {
            $p = Split-Path $ManualPath -Parent
            if (Split-Path $p -Leaf -ieq "app") { return (Split-Path $p -Parent) }
            return $p
        }
        return $ManualPath
    }

    # 1. 執行中行程即時動態偵測 (無論安裝於任何磁碟槽 C/D/E，只要正在執行即可精準定位實體路徑)
    try {
        $runningProcesses = Get-Process -Name "claude" -ErrorAction SilentlyContinue
        foreach ($proc in $runningProcesses) {
            try {
                $mainModule = $proc.MainModule.FileName
                if ($mainModule -and (Test-Path -LiteralPath $mainModule)) {
                    $dir = Split-Path -Parent $mainModule
                    if (Split-Path $dir -Leaf -ieq "app") {
                        $root = Split-Path $dir -Parent
                        if (Test-Path -LiteralPath (Join-Path $root "app\resources")) { return $root }
                    }
                    if (Test-Path -LiteralPath (Join-Path $dir "resources")) { return $dir }
                    if (Test-Path -LiteralPath (Join-Path $dir "app\resources")) { return $dir }
                }
            } catch {}
        }
    } catch {}

    # 2. Windows Store / MSIX 套件動態查詢 (支援任意 Publisher ID 與不同版本)
    try {
        $pkgs = Get-AppxPackage -Name "*Claude*" -ErrorAction SilentlyContinue |
            Sort-Object Version -Descending
        foreach ($pkg in $pkgs) {
            if ($pkg.InstallLocation -and (Test-Path -LiteralPath $pkg.InstallLocation)) {
                if (Test-Path -LiteralPath (Join-Path $pkg.InstallLocation "app\resources")) {
                    return $pkg.InstallLocation
                }
            }
        }
    } catch {}

    # 3. 系統 Appx 註冊表部署全量檢索 (覆蓋所有使用者安裝的所有 Claude 套件)
    try {
        $regDeployPaths = @(
            "HKLM:\Software\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\Deployments",
            "HKLM:\Software\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\InboxApplications"
        )
        foreach ($regPath in $regDeployPaths) {
            if (Test-Path -LiteralPath $regPath) {
                $deployments = Get-ChildItem -LiteralPath $regPath -ErrorAction SilentlyContinue |
                    Where-Object { $_.PSChildName -like "*Claude*" } |
                    Sort-Object PSChildName -Descending
                foreach ($dep in $deployments) {
                    foreach ($drive in [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.IsReady -and $_.DriveType -eq 'Fixed' }) {
                        $candidate = Join-Path $drive.RootDirectory.FullName "Program Files\WindowsApps\$($dep.PSChildName)"
                        if (Test-Path -LiteralPath (Join-Path $candidate "app\resources")) {
                            return $candidate
                        }
                        $candidate2 = Join-Path $drive.RootDirectory.FullName "WindowsApps\$($dep.PSChildName)"
                        if (Test-Path -LiteralPath (Join-Path $candidate2 "app\resources")) {
                            return $candidate2
                        }
                    }
                }
            }
        }
    } catch {}

    # 4. Windows 卸載註冊表動態檢索 (支援自訂路徑安裝、桌面標準安裝)
    try {
        $uninstallKeys = @(
            "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*",
            "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*",
            "HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*"
        )
        foreach ($k in $uninstallKeys) {
            $items = Get-ItemProperty -Path $k -ErrorAction SilentlyContinue |
                Where-Object { $_.DisplayName -like "*Claude*" }
            foreach ($item in $items) {
                if ($item.InstallLocation -and (Test-Path -LiteralPath $item.InstallLocation)) {
                    $res = Join-Path $item.InstallLocation "resources"
                    $appRes = Join-Path $item.InstallLocation "app\resources"
                    if ((Test-Path -LiteralPath $res) -or (Test-Path -LiteralPath $appRes)) {
                        return $item.InstallLocation
                    }
                }
                if ($item.DisplayIcon -and (Test-Path -LiteralPath $item.DisplayIcon)) {
                    $dir = Split-Path -Parent $item.DisplayIcon
                    if (Split-Path $dir -Leaf -ieq "app") {
                        $root = Split-Path $dir -Parent
                        if (Test-Path -LiteralPath (Join-Path $root "app\resources")) { return $root }
                    }
                    if (Test-Path -LiteralPath (Join-Path $dir "resources")) { return $dir }
                }
            }
        }
    } catch {}

    # 5. 開始功能表捷徑動態解析 (.lnk 解析實際 target)
    try {
        $wsh = New-Object -ComObject WScript.Shell
        $lnkDirs = @(
            (Join-Path ${env:APPDATA} "Microsoft\Windows\Start Menu\Programs"),
            (Join-Path ${env:ProgramData} "Microsoft\Windows\Start Menu\Programs")
        )
        foreach ($ld in $lnkDirs) {
            if (Test-Path -LiteralPath $ld) {
                $lnks = Get-ChildItem -LiteralPath $ld -Filter "*Claude*.lnk" -Recurse -File -ErrorAction SilentlyContinue
                foreach ($lnk in $lnks) {
                    try {
                        $target = $wsh.CreateShortcut($lnk.FullName).TargetPath
                        if ($target -and (Test-Path -LiteralPath $target)) {
                            $dir = Split-Path -Parent $target
                            if (Split-Path $dir -Leaf -ieq "app") {
                                $root = Split-Path $dir -Parent
                                if (Test-Path -LiteralPath (Join-Path $root "app\resources")) { return $root }
                            }
                            if (Test-Path -LiteralPath (Join-Path $dir "resources")) { return $dir }
                        }
                    } catch {}
                }
            }
        }
    } catch {}

    # 6. 全磁碟常見安裝路徑動態掃描 (C:, D:, E:, etc.)
    $fixedDrives = [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.IsReady -and $_.DriveType -eq 'Fixed' }
    foreach ($drive in $fixedDrives) {
        $root = $drive.RootDirectory.FullName
        $candidates = @(
            (Join-Path $root "Program Files\WindowsApps"),
            (Join-Path $root "Program Files\Claude"),
            (Join-Path $root "Program Files\Anthropic\Claude"),
            (Join-Path $root "Program Files (x86)\Claude"),
            (Join-Path $root "Program Files (x86)\Anthropic\Claude"),
            (Join-Path ${env:LOCALAPPDATA} "Programs\Claude"),
            (Join-Path ${env:LOCALAPPDATA} "Claude")
        )
        foreach ($c in $candidates) {
            if (-not (Test-Path -LiteralPath $c)) { continue }
            if ($c -like "*WindowsApps") {
                $appxDirs = Get-ChildItem -LiteralPath $c -Directory -Filter "*Claude*" -ErrorAction SilentlyContinue |
                    Sort-Object Name -Descending
                foreach ($ad in $appxDirs) {
                    if (Test-Path -LiteralPath (Join-Path $ad.FullName "app\resources")) {
                        return $ad.FullName
                    }
                }
            } else {
                if (Test-Path -LiteralPath (Join-Path $c "resources")) { return $c }
                if (Test-Path -LiteralPath (Join-Path $c "app\resources")) { return $c }
            }
        }
    }

    return $null
}

function Get-ResourcesPath {
    param([Parameter(Mandatory = $true)][string]$ClaudePath)
    $res1 = Join-Path $ClaudePath "app\resources"
    if (Test-Path -LiteralPath $res1) { return $res1 }
    $res2 = Join-Path $ClaudePath "resources"
    if (Test-Path -LiteralPath $res2) { return $res2 }
    if (Split-Path $ClaudePath -Leaf -ieq "resources") { return $ClaudePath }
    return $null
}

function Grant-WriteAccess {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [switch]$Recursive
    )
    if (-not (Test-Path -LiteralPath $Path)) { return }
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent().Name
    if (-not $identity) { return }

    $isContainer = Test-Path -LiteralPath $Path -PathType Container
    $icaclsExitCode = 0
    if ($isContainer -and $Recursive) {
        & takeown.exe /f $Path /r /d Y >$null 2>&1
        & icacls.exe $Path /grant "${identity}:(OI)(CI)F" /t /c /q >$null 2>&1
        $icaclsExitCode = $LASTEXITCODE
        & attrib.exe -R "$Path\*.*" /S /D >$null 2>&1
    } else {
        & takeown.exe /f $Path /a >$null 2>&1
        if ($isContainer) {
            & icacls.exe $Path /grant "${identity}:(OI)(CI)F" /q >$null 2>&1
        } else {
            & icacls.exe $Path /grant "${identity}:F" /q >$null 2>&1
        }
        $icaclsExitCode = $LASTEXITCODE
        & attrib.exe -R $Path >$null 2>&1
    }

    if ($icaclsExitCode -ne 0) {
        throw "無法授予目前使用者對路徑的寫入權限: $Path (icacls 結束代碼: $icaclsExitCode)。請確認已核准系統管理員權限，並關閉 Claude Desktop 後重試。"
    }
}

function Grant-ExistingFileWriteAccess {
    param([Parameter(Mandatory = $true)][string]$Path)
    if (Test-Path -LiteralPath $Path -PathType Leaf) {
        Grant-WriteAccess -Path $Path
    }
}

function Backup-File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $false)][string]$RelativeTo = ""
    )
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        return
    }
    if ($RelativeTo -and $Path.StartsWith($RelativeTo, [System.StringComparison]::OrdinalIgnoreCase)) {
        $relative = $Path.Substring($RelativeTo.Length).TrimStart("\")
    } else {
        $relative = Split-Path $Path -Leaf
    }
    $destination = Join-Path $backupDir $relative
    $destFolder = Split-Path -Parent $destination
    if (-not (Test-Path -LiteralPath $destFolder)) {
        [System.IO.Directory]::CreateDirectory($destFolder) | Out-Null
    }
    if (-not (Test-Path -LiteralPath $destination -PathType Leaf)) {
        Copy-Item -LiteralPath $Path -Destination $destination -Force
    }
}

function Get-BackupPath {
    param(
        [Parameter(Mandatory = $true)][string]$OriginalPath,
        [Parameter(Mandatory = $false)][string]$RelativeTo = ""
    )
    if ($RelativeTo -and $OriginalPath.StartsWith($RelativeTo, [System.StringComparison]::OrdinalIgnoreCase)) {
        $relative = $OriginalPath.Substring($RelativeTo.Length).TrimStart("\")
    } else {
        $relative = Split-Path $OriginalPath -Leaf
    }
    return (Join-Path $backupDir $relative)
}

function Grant-DirectoryAccessRecursive {
    param([Parameter(Mandatory = $true)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return }

    # 1. 解鎖 resources 根目錄 (供寫入 zh-TW.json)
    Grant-WriteAccess -Path $Path

    # 2. 解鎖 ion-dist 與 i18n 語系目錄
    $ionDist = Join-Path $Path "ion-dist"
    if (Test-Path -LiteralPath $ionDist) { Grant-WriteAccess -Path $ionDist }

    $i18nDir = Join-Path $Path "ion-dist\i18n"
    if (Test-Path -LiteralPath $i18nDir) { Grant-WriteAccess -Path $i18nDir -Recursive }

    $assetsDir = Join-Path $Path "ion-dist\assets\v1"
    if (Test-Path -LiteralPath $assetsDir) { Grant-WriteAccess -Path $assetsDir }
}

function Patch-JsLanguage {
    param(
        [Parameter(Mandatory = $true)][string]$ResourcesPath,
        [switch]$Silent
    )
    $assetsDir = Join-Path $ResourcesPath "ion-dist\assets\v1"
    if (-not (Test-Path -LiteralPath $assetsDir -PathType Container)) {
        if (-not $Silent) { Write-Host "  [警告] 找不到 assets 目錄，跳過 JS 補丁" -ForegroundColor Yellow }
        return $false
    }

    # 優先檢索 shared-*.js（99% 語言白名單位於 shared-*.js 中），若無則掃描所有 js
    $jsFiles = Get-ChildItem -LiteralPath $assetsDir -Filter "shared-*.js" -File -ErrorAction SilentlyContinue
    if (-not $jsFiles -or $jsFiles.Count -eq 0) {
        $jsFiles = Get-ChildItem -LiteralPath $assetsDir -Filter "*.js" -File -ErrorAction SilentlyContinue
    }

    $regexAdd = [regex]'((?:[\w$]+)=\["en-US"(?:,"[^"]+")+)\]'
    $patched = $false

    foreach ($jsFile in $jsFiles) {
        $content = [System.IO.File]::ReadAllText($jsFile.FullName)
        if (-not $content.Contains('["en-US"')) {
            continue
        }

        if ($content.Contains('"zh-TW"')) {
            if (-not $Silent) { Write-Host "  已註冊語言: $($jsFile.Name)" -ForegroundColor DarkGray }
            $patched = $true
            continue
        }

        $newContent = $regexAdd.Replace($content, '$1,"zh-TW"]', 1)
        if ($newContent -ne $content) {
            Grant-WriteAccess -Path $jsFile.FullName
            Backup-File -Path $jsFile.FullName -RelativeTo $ResourcesPath
            Write-Utf8File -Path $jsFile.FullName -Content $newContent
            if (-not $Silent) { Write-Host "  JS 語言白名單已修補: $($jsFile.Name)" -ForegroundColor Green }
            $patched = $true
        }
    }
    return $patched
}

function Unpatch-JsLanguage {
    param([Parameter(Mandatory = $true)][string]$ResourcesPath)
    $assetsDir = Join-Path $ResourcesPath "ion-dist\assets\v1"
    if (-not (Test-Path -LiteralPath $assetsDir -PathType Container)) {
        return
    }

    $jsFiles = Get-ChildItem -LiteralPath $assetsDir -Filter "shared-*.js" -File -ErrorAction SilentlyContinue
    if (-not $jsFiles -or $jsFiles.Count -eq 0) {
        $jsFiles = Get-ChildItem -LiteralPath $assetsDir -Filter "*.js" -File -ErrorAction SilentlyContinue
    }

    $regexRemove = [regex]'((?:[\w$]+)=\[(?:"[^"]+",)+)"zh-TW"\]'

    foreach ($jsFile in $jsFiles) {
        $backupPath = Get-BackupPath -OriginalPath $jsFile.FullName -RelativeTo $ResourcesPath
        if (Test-Path -LiteralPath $backupPath -PathType Leaf) {
            Grant-WriteAccess -Path $jsFile.FullName
            Copy-Item -LiteralPath $backupPath -Destination $jsFile.FullName -Force
            Write-Host "  從備份還原: $($jsFile.Name)" -ForegroundColor Green
            continue
        }

        $content = [System.IO.File]::ReadAllText($jsFile.FullName)
        if (-not $content.Contains('"zh-TW"')) {
            continue
        }
        $newContent = $regexRemove.Replace($content, '$1]', 1)
        if ($newContent -ne $content) {
            Grant-WriteAccess -Path $jsFile.FullName
            Write-Utf8File -Path $jsFile.FullName -Content $newContent
            Write-Host "  語言註冊已還原: $($jsFile.Name)" -ForegroundColor Green
        }
    }

    if (Test-Path -LiteralPath $backupDir -PathType Container) {
        Remove-Item -LiteralPath $backupDir -Recurse -Force -ErrorAction SilentlyContinue
    }
}

function Update-Config {
    param(
        [Parameter(Mandatory = $true)][string]$Locale,
        [switch]$Silent
    )
    $configPaths = [System.Collections.Generic.List[string]]::new()

    # 1. 掃描標準 AppData 目錄
    $appDataConfigs = @(
        (Join-Path ${env:APPDATA} "Claude\config.json"),
        (Join-Path ${env:APPDATA} "Claude-3p\config.json"),
        (Join-Path ${env:LOCALAPPDATA} "Claude\config.json")
    )
    foreach ($cfg in $appDataConfigs) {
        if (Test-Path -LiteralPath $cfg -PathType Leaf) {
            $configPaths.Add($cfg)
        }
    }

    # 2. 動態遍歷 LocalAppData\Packages 下所有 Claude 套件（絕不寫死 PackageFamilyName）
    $packagesDir = Join-Path ${env:LOCALAPPDATA} "Packages"
    if (Test-Path -LiteralPath $packagesDir -PathType Container) {
        $claudePackages = Get-ChildItem -LiteralPath $packagesDir -Directory -Filter "*Claude*" -ErrorAction SilentlyContinue
        foreach ($pkgDir in $claudePackages) {
            $c1 = Join-Path $pkgDir.FullName "LocalCache\Roaming\Claude\config.json"
            $c2 = Join-Path $pkgDir.FullName "LocalCache\Roaming\Claude-3p\config.json"
            if (Test-Path -LiteralPath $c1 -PathType Leaf) { $configPaths.Add($c1) }
            if (Test-Path -LiteralPath $c2 -PathType Leaf) { $configPaths.Add($c2) }
        }
    }

    foreach ($configPath in $configPaths) {
        try {
            $raw = Get-Content -LiteralPath $configPath -Raw -Encoding UTF8
            if ($raw -match '"locale"\s*:') {
                $newRaw = $raw -replace '("locale"\s*:\s*)"[^"]*"', "`$1`"$Locale`""
            } else {
                $newRaw = $raw -replace '(\s*)\}(\s*)$', ",`r`n  `"locale`": `"$Locale`"`$1}`$2"
            }
            Write-Utf8File -Path $configPath -Content $newRaw
            if (-not $Silent) {
                Write-Host "  偏好設定更新成功: $(Split-Path $configPath -Leaf) (語言: $Locale)" -ForegroundColor Green
            }
        } catch {}
    }
}

function Register-AutoHealTask {
    param([Parameter(Mandatory = $true)][string]$ScriptPath)
    $taskName = "Claude-zh-TW-AutoHeal"
    try {
        $arg = "-WindowStyle Hidden -ExecutionPolicy Bypass -NoProfile -File `"$ScriptPath`" -AutoHeal -Silent"
        $createOutput = & schtasks.exe /create /tn $taskName /tr "powershell.exe $arg" /sc onlogon /rl highest /f 2>&1
        if ($LASTEXITCODE -eq 0) {
            Write-Host "  已註冊自動守護排程 (小版本更新不失效): $taskName" -ForegroundColor Green
        } else {
            Write-Host "  [提示] 自動守護排程設定略過: $createOutput" -ForegroundColor DarkGray
        }
    } catch {
        Write-Host "  [提示] 自動守護排程設定略過: $($_.Exception.Message)" -ForegroundColor DarkGray
    }
}

function Unregister-AutoHealTask {
    $taskName = "Claude-zh-TW-AutoHeal"
    try {
        & schtasks.exe /delete /tn $taskName /f 2>&1 | Out-Null
        Write-Host "  已移除自動守護排程: $taskName" -ForegroundColor Green
    } catch {}
}

function Test-NeedsHeal {
    param([Parameter(Mandatory = $true)][string]$ResourcesPath)
    $i18nZhTw = Join-Path $ResourcesPath "ion-dist\i18n\zh-TW.json"
    $shellZhTw = Join-Path $ResourcesPath "zh-TW.json"
    if ((-not (Test-Path -LiteralPath $i18nZhTw -PathType Leaf)) -or (-not (Test-Path -LiteralPath $shellZhTw -PathType Leaf))) {
        return $true
    }

    $assetsDir = Join-Path $ResourcesPath "ion-dist\assets\v1"
    if (Test-Path -LiteralPath $assetsDir -PathType Container) {
        $jsFiles = Get-ChildItem -LiteralPath $assetsDir -Filter "shared-*.js" -File -ErrorAction SilentlyContinue
        if (-not $jsFiles -or $jsFiles.Count -eq 0) {
            $jsFiles = Get-ChildItem -LiteralPath $assetsDir -Filter "*.js" -File -ErrorAction SilentlyContinue
        }
        $patched = $false
        foreach ($js in $jsFiles) {
            $txt = [System.IO.File]::ReadAllText($js.FullName)
            if ($txt.Contains('["en-US"') -and $txt.Contains('"zh-TW"')) {
                $patched = $true
                break
            }
        }
        if (-not $patched) {
            return $true
        }
    }
    return $false
}

function Do-AutoHeal {
    $claudePath = Find-ClaudePath
    if (-not $claudePath) { return }
    $resourcesPath = Get-ResourcesPath -ClaudePath $claudePath
    if (-not $resourcesPath) { return }

    if (-not (Test-NeedsHeal -ResourcesPath $resourcesPath)) {
        return
    }

    try {
        Do-Install -SilentInstall -NoRestart
        $logDir = Join-Path ${env:LOCALAPPDATA} "Claude-zh-TW"
        if (-not (Test-Path -LiteralPath $logDir)) {
            [System.IO.Directory]::CreateDirectory($logDir) | Out-Null
        }
        $logFile = Join-Path $logDir "autoheal.log"
        $now = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
        [System.IO.File]::AppendAllText($logFile, "[$now] 偵測到 Claude 小版本更新，已自動修復繁體中文在地化！`r`n", [System.Text.Encoding]::UTF8)
    } catch {}
}

function Restart-Claude {
    param([string]$ClaudePath = "")
    try {
        Stop-Process -Name "claude" -Force -ErrorAction SilentlyContinue
    } catch {}
    Start-Sleep -Seconds 2

    if (-not $ClaudePath) { $ClaudePath = Find-ClaudePath }
    if (-not $ClaudePath) { return }

    # 1. 嘗試透過 AppxManifest.xml 動態解析啟動
    $manifestPath = Join-Path $ClaudePath "AppxManifest.xml"
    if (Test-Path -LiteralPath $manifestPath -PathType Leaf) {
        try {
            [xml]$manifest = Get-Content -LiteralPath $manifestPath -Raw
            $appId = [string]$manifest.Package.Applications.Application.Id
            $identity = [string]$manifest.Package.Identity.Name

            $pfn = ""
            $pkg = Get-AppxPackage -Name "*$identity*" -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($pkg -and $pkg.PackageFamilyName) {
                $pfn = $pkg.PackageFamilyName
            } else {
                $folderLeaf = Split-Path -Leaf $ClaudePath
                if ($folderLeaf -match "__([^_]+)$") {
                    $pfn = "$identity`_$($Matches[1])"
                }
            }
            if ($pfn -and $appId) {
                Start-Process "explorer.exe" "shell:AppsFolder\$pfn!$appId" | Out-Null
                Start-Sleep -Seconds 3
                Write-Host "Claude Desktop 已重新啟動！" -ForegroundColor Green
                return
            }
        } catch {}
    }

    # 2. 尋找 claude.exe
    $exeCandidates = @(
        (Join-Path $ClaudePath "app\claude.exe"),
        (Join-Path $ClaudePath "claude.exe"),
        (Join-Path $ClaudePath "Claude.exe")
    )
    foreach ($exe in $exeCandidates) {
        if (Test-Path -LiteralPath $exe) {
            Start-Process "explorer.exe" "`"$exe`"" | Out-Null
            Start-Sleep -Seconds 3
            Write-Host "Claude Desktop 已重新啟動！" -ForegroundColor Green
            return
        }
    }
}

function Print-Banner {
    Write-Host ""
    Write-Host "  ========================================================" -ForegroundColor Cyan
    Write-Host "        Claude Desktop 臺灣正體中文語言包 (zh-TW)        " -ForegroundColor Cyan
    Write-Host "       道地臺灣習慣用語 · 自動守護小版本更新不失效       " -ForegroundColor DarkCyan
    Write-Host "  ========================================================" -ForegroundColor Cyan
    Write-Host ""
}

function Do-Install {
    param([switch]$SilentInstall)

    if (-not $SilentInstall) {
        Print-Banner
        Write-Host "=== 開始安裝繁體中文語言包 ==="
        Write-Host ""
        Write-Host "[1/6] 尋找 Claude Desktop 安裝目錄..."
    }

    $claudePath = Find-ClaudePath -ManualPath $Path
    if (-not $claudePath) {
        if (-not $SilentInstall) {
            Write-Host ""
            Write-Host "  [提示] 系統多層動態檢索未能自動鎖定 Claude 安裝目錄。" -ForegroundColor Yellow
            $userInput = Read-Host "請輸入或拖曳 Claude 安裝目錄 (例如 C:\Program Files\WindowsApps\Claude... 或 D:\Claude)"
            if ($userInput) {
                $userInput = $userInput.Trim('"', "'", " ")
                $claudePath = Find-ClaudePath -ManualPath $userInput
            }
        }
    }
    if (-not $claudePath) {
        throw "未偵測到已安裝的 Claude Desktop！請確認 Claude Desktop 是否已安裝。"
    }
    $resourcesPath = Get-ResourcesPath -ClaudePath $claudePath
    if (-not $resourcesPath) {
        throw "找不到 resources 目錄: $claudePath\app\resources"
    }

    if (-not $SilentInstall) {
        Write-Host "  發現 Claude 目錄: $claudePath" -ForegroundColor Green
        Write-Host ""
        Write-Host "[2/6] 取得目錄寫入權限..."
    }

    Grant-DirectoryAccessRecursive -Path $resourcesPath

    if (-not $SilentInstall) {
        Write-Host "  目錄權限解鎖完成" -ForegroundColor Green
        Write-Host ""
        Write-Host "[3/6] 部署臺灣正體中文在地化語系檔案..."
    }

    $localesDir = Join-Path $PSScriptRoot "locales"
    $hasLocalFiles = (Test-Path -LiteralPath (Join-Path $localesDir "ion-dist.json") -PathType Leaf) -and
                     (Test-Path -LiteralPath (Join-Path $localesDir "desktop-shell.json") -PathType Leaf) -and
                     (Test-Path -LiteralPath (Join-Path $localesDir "statsig.json") -PathType Leaf)

    if ($hasLocalFiles) {
        if (-not $SilentInstall) {
            Write-Host "  [來源] 優先載入 locales 目錄語系檔案..." -ForegroundColor Cyan
        }
        $localeFiles = @(
            @{ Source = "ion-dist.json"; Destinations = @("ion-dist\i18n\zh-TW.json", "ion-dist\i18n\zh-Hant.json") },
            @{ Source = "desktop-shell.json"; Destinations = @("zh-TW.json", "zh-Hant.json") },
            @{ Source = "statsig.json"; Destinations = @("ion-dist\i18n\statsig\zh-TW.json", "ion-dist\i18n\statsig\zh-Hant.json") },
            @{ Source = "dynamic.json"; Destinations = @("ion-dist\i18n\dynamic\zh-TW.json", "ion-dist\i18n\dynamic\zh-Hant.json") }
        )
        foreach ($localeFile in $localeFiles) {
            $sourcePath = Join-Path $localesDir $localeFile.Source
            foreach ($relativeDestination in $localeFile.Destinations) {
                $destinationPath = Join-Path $resourcesPath $relativeDestination
                Grant-ExistingFileWriteAccess -Path $destinationPath
                Copy-Item -LiteralPath $sourcePath -Destination $destinationPath -Force
            }
        }
    } else {
        if (-not $SilentInstall) {
            Write-Host "  [來源] 載入腳本內建臺灣正體中文資源庫..." -ForegroundColor Cyan
        }
        Decompress-B64GzToFile -Base64 $B64_ION -OutPath (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.json")
        Decompress-B64GzToFile -Base64 $B64_ION -OutPath (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.json")
        Decompress-B64GzToFile -Base64 $B64_DESKTOP -OutPath (Join-Path $resourcesPath "zh-TW.json")
        Decompress-B64GzToFile -Base64 $B64_DESKTOP -OutPath (Join-Path $resourcesPath "zh-Hant.json")
        Decompress-B64GzToFile -Base64 $B64_STATSIG -OutPath (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-TW.json")
        Decompress-B64GzToFile -Base64 $B64_STATSIG -OutPath (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-Hant.json")
        Decompress-B64GzToFile -Base64 $B64_DYNAMIC -OutPath (Join-Path $resourcesPath "ion-dist\i18n\dynamic\zh-TW.json")
        Decompress-B64GzToFile -Base64 $B64_DYNAMIC -OutPath (Join-Path $resourcesPath "ion-dist\i18n\dynamic\zh-Hant.json")
    }

    # 寫入 overrides 佔位檔
    Grant-ExistingFileWriteAccess -Path (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.overrides.json")
    Grant-ExistingFileWriteAccess -Path (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.overrides.json")
    Write-Utf8File -Path (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.overrides.json") -Content "{}`n"
    Write-Utf8File -Path (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.overrides.json") -Content "{}`n"

    if (-not $SilentInstall) {
        Write-Host "  → ion-dist\i18n\zh-TW.json (全量 41,699 條前端介面在地化，涵蓋最新功能)" -ForegroundColor Green
        Write-Host "  → zh-TW.json (837 條視窗與系統選單在地化)" -ForegroundColor Green
        Write-Host "  → ion-dist\i18n\statsig\zh-TW.json (模型與功能提示文案)" -ForegroundColor Green
        Write-Host "  → ion-dist\i18n\zh-TW.overrides.json (防止前端 404)" -ForegroundColor Green
        Write-Host ""
        Write-Host "[4/6] 註冊繁體中文語言 (zh-TW)..."
    }

    [void](Patch-JsLanguage -ResourcesPath $resourcesPath -Silent:$SilentInstall)

    if (-not $SilentInstall) {
        Write-Host ""
        Write-Host "[5/6] 更新偏好設定..."
    }
    Update-Config -Locale "zh-TW" -Silent:$SilentInstall

    if (-not $SilentInstall) {
        Write-Host ""
        Write-Host "[6/6] 註冊自動守護排程 (小版本更新不失效)..."
    }
    Register-AutoHealTask -ScriptPath $PSCommandPath

    if (-not $SilentInstall) {
        Write-Host ""
        Write-Host "=========================================" -ForegroundColor Green
        Write-Host "  恭喜！繁體中文語言包已順利安裝完成！  " -ForegroundColor Green
        Write-Host "=========================================" -ForegroundColor Green

        if ($NoRestart) {
            Write-Host "請手動重新啟動 Claude Desktop。"
        } else {
            Write-Host ""
            Restart-Claude
        }
    }
}

function Do-Uninstall {
    Print-Banner
    Write-Host "=== 開始解除安裝繁體中文語言包 ==="
    Write-Host ""

    $claudePath = Find-ClaudePath
    if (-not $claudePath) {
        throw "未偵測到已安裝的 Claude Desktop"
    }
    $resourcesPath = Get-ResourcesPath -ClaudePath $claudePath

    Write-Host "[1/4] 清理語言包檔案..."
    foreach ($path in @(
            (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\zh-TW.overrides.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\zh-Hant.overrides.json"),
            (Join-Path $resourcesPath "zh-TW.json"),
            (Join-Path $resourcesPath "zh-Hant.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-TW.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\statsig\zh-Hant.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\dynamic\zh-TW.json"),
            (Join-Path $resourcesPath "ion-dist\i18n\dynamic\zh-Hant.json")
        )) {
        if (Test-Path -LiteralPath $path -PathType Leaf) {
            Grant-WriteAccess -Path $path
            Remove-Item -LiteralPath $path -Force
        }
    }
    Write-Host "  已移除語言包檔案" -ForegroundColor Green

    Write-Host ""
    Write-Host "[2/4] 還原前端 JS 語言註冊..."
    Unpatch-JsLanguage -ResourcesPath $resourcesPath

    Write-Host ""
    Write-Host "[3/4] 還原預設偏好設定為英文 (en-US)..."
    Update-Config -Locale "en-US"

    Write-Host ""
    Write-Host "[4/4] 移除自動守護排程..."
    Unregister-AutoHealTask

    Write-Host ""
    Write-Host "=== 繁體中文語言包解除安裝完成 ===" -ForegroundColor Green

    if ($NoRestart) {
        Write-Host "請手動重新啟動 Claude Desktop。"
    } else {
        Write-Host ""
        Restart-Claude
    }
}

$scriptArgs = @()
if ($Path) {
    $scriptArgs += @("-Path", "`"$Path`"")
}
if ($Uninstall) {
    $scriptArgs += "-Uninstall"
}
if ($Install) {
    $scriptArgs += "-Install"
}
if ($AutoHeal) {
    $scriptArgs += "-AutoHeal"
}
if ($Silent) {
    $scriptArgs += "-Silent"
}
if ($NoRestart) {
    $scriptArgs += "-NoRestart"
}
if ($PauseAtEnd) {
    $scriptArgs += "-PauseAtEnd"
}

Ensure-Administrator -Arguments $scriptArgs

try {
    if ($AutoHeal) {
        Do-AutoHeal
        exit 0
    }
    elseif ($Uninstall) {
        Do-Uninstall
    }
    elseif ($Install) {
        Do-Install
    }
    else {
        Print-Banner
        Write-Host "請選擇您要執行的操作：" -ForegroundColor Yellow
        Write-Host "  [1] 安裝繁體中文語言包 (zh-TW)" -ForegroundColor Cyan
        Write-Host "  [2] 解除安裝繁體中文語言包 (還原為英文原版)" -ForegroundColor Cyan
        Write-Host "  [0] 離開"
        Write-Host ""
        $choice = Read-Host "請輸入選項編號 [預設: 1]"
        if ($choice -eq "2") {
            Do-Uninstall
        } elseif ($choice -eq "0") {
            exit 0
        } else {
            Do-Install
        }
    }
}
catch {
    if (-not $Silent) {
        Write-Host ""
        Write-Host "[錯誤] $($_.Exception.Message)" -ForegroundColor Red
    }
}
finally {
    Wait-BeforeExit
}
